/**
 * WISDOM BANK F — taoism (26 compact entries).
 */

import type { WisdomArchetype } from "./types";

export const WISDOM_TAOISM: WisdomArchetype[] = [
  { concept: "The Tao That Can Be Told Is Not the Eternal Tao", tradition: "Taoism", source: "Tao Te Ching 1", explanation: "The Tao Te Ching's opening: the Tao that can be told is not the eternal Tao. The name that can be named is not the eternal name. The teaching's precision: the absolute is not a concept but the ground of concepts — naming is the beginning of the limitation.", application: "Use the opening as the library's epistemology: every entry names, and naming limits. The application is the naming's awareness — the concept is the finger, the Tao is the moon. Read the entry, then look where it points.", questions: ["What is the Tao — and why can't it be told?", "Where is my naming limiting my seeing?", "Can I read an entry and look past it?"], references: ["Tao Te Ching 1", "Tao Te Ching 2", "Zhuangzi"], excerpt: "The Tao that can be told is not the eternal Tao. The name that can be named is not the eternal name.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["tao", "jnana"], domains: ["spirituality", "learning"], tags: ["taoism", "tao_te_ching", "tao", "name", "eternal", "limit", "epistemology"], difficulty: "advanced", minutes: 6 },
  { concept: "The Ten Thousand Things", tradition: "Taoism", source: "Tao Te Ching 1", explanation: "The Tao Te Ching: the nameless is the beginning of heaven and earth; the named is the mother of the ten thousand things. The teaching's precision: the unnamed is the source; the named is the display. Both are the same reality, seen from different angles.", application: "Use the ten thousand things as the library's cosmology: every entry is one of the ten thousand — named, displayed, and ultimately returning to the nameless. The application is the named's awareness: the entry is used, the nameless is recognized.", questions: ["What is the relationship between the named and the nameless?", "Where is my mind clinging to the named?", "Can I use the named while resting in the nameless?"], references: ["Tao Te Ching 1", "Tao Te Ching 25", "Zhuangzi 17"], excerpt: "The nameless is the beginning of heaven and earth; the named is the mother of the ten thousand things.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["tao", "jnana"], domains: ["spirituality", "learning"], tags: ["taoism", "ten_thousand_things", "named", "nameless", "display", "source"], difficulty: "intermediate", minutes: 6 },
  { concept: "Wu Wei — Non-Action", tradition: "Taoism", source: "Tao Te Ching 2, 3, 37, 43", explanation: "Wu wei — non-action, or action without forcing. The Tao Te Ching's central teaching: the sage acts without acting, accomplishes without doing, teaches without words. The precision: wu wei is not passivity but alignment — action that follows the Tao's current rather than opposing it.", application: "Use wu wei as the library's action teaching: in the next task, act without forcing. The application is the forcing's recognition — where am I pushing against the current? The forcing's release is the action's improvement, not its abandonment.", questions: ["Where am I forcing — and what is the current I am opposing?", "What is the difference between wu wei and passivity?", "Can I act fully while forcing nothing?"], references: ["Tao Te Ching 2", "Tao Te Ching 3", "Tao Te Ching 37", "Tao Te Ching 43"], excerpt: "The sage acts without acting; accomplishes without doing; teaches without words.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["tao", "karma"], domains: ["work", "growth"], tags: ["taoism", "wu_wei", "non_action", "forcing", "alignment", "current", "sage"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Valley Spirit — The Mysterious Feminine", tradition: "Taoism", source: "Tao Te Ching 6", explanation: "The Tao Te Ching's image: the valley spirit never dies; it is called the mysterious feminine. The gate of the mysterious feminine is the root of heaven and earth. The teaching's precision: the feminine — receptive, low, empty — is the root of all creation, not the masculine — active, high, full.", application: "Use the valley spirit as the library's receptivity teaching: the practice's root is not the active mind but the receptive space. The application is the receptivity's cultivation — the empty valley receives; the full hill does not.", questions: ["Where is my practice's receptivity — and where is its activity?", "What is the difference between the valley (receptive) and the hill (full)?", "Can I cultivate receptivity without abandoning action?"], references: ["Tao Te Ching 6", "Tao Te Ching 28", "Zhuangzi 6"], excerpt: "The valley spirit never dies; it is called the mysterious feminine. The gate of the mysterious feminine is the root.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["tao", "bhakti"], domains: ["spirituality", "growth"], tags: ["taoism", "valley_spirit", "feminine", "receptive", "empty", "root", "creation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Uncarved Block — Pu", tradition: "Taoism", source: "Tao Te Ching 15, 19, 28, 32, 37, 57", explanation: "Pu — the uncarved block — the Taoist image of original simplicity, before naming, before carving, before the mind's divisions. The teaching's precision: the block is not ignorant but uncarved — the potential is present, the form is not yet imposed. The sage values the uncarved block's simplicity.", application: "Use the uncarved block as the library's simplicity teaching: the practice's goal is not the mind's carving but its return to the uncarved. The application is the carving's recognition — where is the mind carving what was already whole?", questions: ["Where is my mind carving what was already whole?", "What is the difference between the uncarved (potential) and the ignorant (blank)?", "Can I value the uncarved — not as primitive but as complete?"], references: ["Tao Te Ching 15", "Tao Te Ching 19", "Tao Te Ching 28", "Tao Te Ching 37"], excerpt: "The sage values the uncarved block — simplicity before naming.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "growth"], tags: ["taoism", "uncarved_block", "pu", "simplicity", "original", "carving", "potential"], difficulty: "beginner", minutes: 6 },
  { concept: "The Soft Overcomes the Hard", tradition: "Taoism", source: "Tao Te Ching 36, 43, 76, 78", explanation: "The Tao Te Ching's repeated teaching: the soft overcomes the hard; the weak overcomes the strong. Water wears away stone; the infant's softness is the strongest. The teaching's precision: not a tactic but a law — the hard is the surface; the soft is the substance. The hard breaks; the soft endures.", application: "Use the soft-overcomes-hard as the library's strategy teaching: in any conflict, the soft stance endures; the hard stance breaks. The application is the stance's recognition — where am I hardening, and what would softening look like?", questions: ["Where am I hardening — and what is the hardening's cost?", "What would the soft stance look like in my next conflict?", "Can I distinguish the soft (enduring) from the weak (collapsing)?"], references: ["Tao Te Ching 36", "Tao Te Ching 43", "Tao Te Ching 76", "Tao Te Ching 78"], excerpt: "The soft overcomes the hard; the weak overcomes the strong.", evidence: "traditional", dimensions: ["action", "emotion", "thought"], paths: ["tao", "karma"], domains: ["growth", "relationships", "work"], tags: ["taoism", "soft", "hard", "water", "stone", "enduring", "strategy"], difficulty: "beginner", minutes: 6 },
  { concept: "The Sage Has No Fixed Mind", tradition: "Taoism", source: "Tao Te Ching 20, 49, 58", explanation: "The Tao Te Ching: the sage has no fixed mind; he takes the people's mind as his mind. The teaching's precision: the sage's mind is not empty but responsive — it does not hold a position but receives the situation. The fixed mind is the sage's only obstacle.", application: "Use the no-fixed-mind as the library's responsiveness teaching: in the next decision, hold no position — receive the situation. The application is the position's release — not the mind's emptiness but its responsiveness.", questions: ["Where is my mind fixed — and what is the fixation's cost?", "What would receiving the situation look like?", "Can I distinguish the responsive (no fixed mind) from the empty (no mind)?"], references: ["Tao Te Ching 20", "Tao Te Ching 49", "Tao Te Ching 58"], excerpt: "The sage has no fixed mind; he takes the people's mind as his mind.", evidence: "traditional", dimensions: ["thought", "connection", "spirit"], paths: ["tao", "jnana"], domains: ["work", "relationships", "growth"], tags: ["taoism", "sage", "no_fixed_mind", "responsive", "receiving", "position", "flexibility"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Usefulness of the Empty", tradition: "Taoism", source: "Tao Te Ching 11", explanation: "The Tao Te Ching's famous teaching on emptiness: thirty spokes meet at the hub, but the cart's usefulness is in the empty space. The bowl's usefulness is in the empty space. The room's usefulness is in the empty space. The teaching's precision: the useful is the empty, not the full.", application: "Use the empty-space teaching as the library's design principle: in any system — schedule, mind, home — the empty space is the useful part. The application is the emptiness's protection: guard the empty space as the useful space.", questions: ["Where is my empty space — and am I protecting it?", "What is the difference between the full (the spokes) and the empty (the hub)?", "Can I hold the empty space as the most useful part?"], references: ["Tao Te Ching 11", "Tao Te Ching 45", "Zhuangzi 11"], excerpt: "Thirty spokes meet at the hub, but the cart's usefulness is in the empty space.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["tao", "karma"], domains: ["work", "growth", "self_care"], tags: ["taoism", "empty", "useful", "space", "hub", "bowl", "room", "design"], difficulty: "beginner", minutes: 6 },
  { concept: "The Return — The Movement of the Tao", tradition: "Taoism", source: "Tao Te Ching 14, 16, 40, 52", explanation: "The Tao Te Ching's teaching on return: returning is the movement of the Tao. All things rise and return to their source. The teaching's precision: the return is not a reversal but a recognition — the source was never left; the return is the recognition of the source's presence.", application: "Use the return as the library's cyclical teaching: every practice, every day, returns to the source. The application is the return's awareness — not the source's recovery (it was never lost) but the recognition's regularity.", questions: ["What is my source — and how does my practice return to it?", "Where am I treating the return as a reversal rather than a recognition?", "Can I feel the source's presence in the return's movement?"], references: ["Tao Te Ching 14", "Tao Te Ching 16", "Tao Te Ching 40", "Tao Te Ching 52"], excerpt: "Returning is the movement of the Tao. All things rise and return to their source.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["tao", "jnana"], domains: ["spirituality", "growth"], tags: ["taoism", "return", "movement", "source", "cyclical", "recognition", "returning"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Three Treasures — Compassion, Frugality, Humility", tradition: "Taoism", source: "Tao Te Ching 67", explanation: "The Tao Te Ching's three treasures: compassion (ci), frugality (jian), and humility (bu gan wei tian xia xian — not daring to be first in the world). The teaching's precision: these three are the sage's armor — the three that protect against the world's three forces (war, extravagance, ambition).", application: "Use the three treasures as the library's character curriculum: compassion (the heart's protection), frugality (the action's protection), humility (the ambition's protection). The application is the three's practice — one per week, examined.", questions: ["Which treasure is strongest in me — and which is absent?", "What is the difference between the treasure and its imitation?", "Can I practice all three without making them rules?"], references: ["Tao Te Ching 67", "Tao Te Ching 49", "Tao Te Ching 58"], excerpt: "The three treasures: compassion, frugality, humility. The sage's armor.", evidence: "traditional", dimensions: ["emotion", "action", "spirit"], paths: ["tao", "karma"], domains: ["growth", "ethics", "relationships"], tags: ["taoism", "three_treasures", "compassion", "frugality", "humility", "armor", "sage"], difficulty: "beginner", minutes: 7 },
  { concept: "The Master Does Not Act, Yet Nothing Is Left Undone", tradition: "Taoism", source: "Tao Te Ching 37", explanation: "The Tao Te Ching's paradox: the Tao does not act, yet nothing is left undone. The teaching's precision: the Tao's non-action is not absence but alignment — the doing that follows the Tao's current accomplishes without the doer's force. The master who does not act is the one whose action is the Tao's action.", application: "Use the paradox as the library's efficiency teaching: the most effective action is the least forced. The application is the forcing's release — not the action's abandonment but the doer's release. The work is done; the doer is not.", questions: ["Where is my doing leaving things undone — because of forcing?", "What is the difference between the doer's action and the Tao's action?", "Can I act fully while releasing the doer?"], references: ["Tao Te Ching 37", "Tao Te Ching 3", "Tao Te Ching 43"], excerpt: "The Tao does not act, yet nothing is left undone.", evidence: "traditional", dimensions: ["action", "spirit", "thought"], paths: ["tao", "karma"], domains: ["work", "growth"], tags: ["taoism", "tao_does_not_act", "nothing_left_undone", "paradox", "efficiency", "doer"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Uncarved Block's Simplicity", tradition: "Taoism", source: "Tao Te Ching 15, 19, 28, 32, 37, 57", explanation: "Pu — the uncarved block — the Taoist image of original simplicity, before naming, before carving, before the mind's divisions. The teaching's precision: the block is not ignorant but uncarved — the potential is present, the form is not yet imposed. The sage values the uncarved block's simplicity.", application: "Use the uncarved block as the library's simplicity teaching: the practice's goal is not the mind's carving but its return to the uncarved. The application is the carving's recognition — where is the mind carving what was already whole?", questions: ["Where is my mind carving what was already whole?", "What is the difference between the uncarved (potential) and the ignorant (blank)?", "Can I value the uncarved — not as primitive but as complete?"], references: ["Tao Te Ching 15", "Tao Te Ching 19", "Tao Te Ching 28", "Tao Te Ching 37"], excerpt: "The sage values the uncarved block — simplicity before naming.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "growth"], tags: ["taoism", "uncarved_block", "pu", "simplicity", "original", "carving", "potential"], difficulty: "beginner", minutes: 6 },
  { concept: "The Water's Way — The Lowest and the Highest", tradition: "Taoism", source: "Tao Te Ching 8, 78", explanation: "The Tao Te Ching's water teaching: the highest good is like water — it benefits all things and does not compete; it dwells in the low places that all disdain. The teaching's precision: water's power is its lowness — the low is the high, the receiving is the giving, the yielding is the enduring.", application: "Use the water teaching as the library's humility practice: in the next interaction, dwell in the low place. The application is the lowness's recognition — the low is not the weak but the strong; the receiving is not the passive but the active.", questions: ["Where am I competing — and what would yielding look like?", "What is the difference between the low (strong) and the weak (collapsing)?", "Can I dwell in the low place — the place all disdain — and find its power?"], references: ["Tao Te Ching 8", "Tao Te Ching 78", "Zhuangzi 18"], excerpt: "The highest good is like water — it benefits all things and does not compete; it dwells in the low places.", evidence: "traditional", dimensions: ["action", "emotion", "spirit"], paths: ["tao", "karma"], domains: ["growth", "relationships", "work"], tags: ["taoism", "water", "lowest", "highest", "humility", "yielding", "enduring", "compete"], difficulty: "beginner", minutes: 6 },
  { concept: "The Usefulness of the Useless", tradition: "Taoism", source: "Tao Te Ching 11; Zhuangzi 4", explanation: "The Zhuangzi's teaching on the useless tree: the tree that is useless for timber is not cut — and so it lives long. The teaching's precision: the useless is the useful — the tree's uselessness is its life. The teaching extends to the person: the useless person is the one who is not used up.", application: "Use the useless-tree teaching as the library's counter-efficiency teaching: not everything must be useful. The application is the uselessness's protection — the practice that does not produce is not wasted; the person who is not used up is the one who endures.", questions: ["Where am I demanding usefulness — and what is the demand's cost?", "What is my useless tree — the practice that does not produce?", "Can I hold the useless as the useful — without irony?"], references: ["Zhuangzi 4 (The Human World)", "Tao Te Ching 11", "Zhuangzi 1"], excerpt: "The useless tree is not cut — and so it lives long. The useless is the useful.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["tao", "jnana"], domains: ["growth", "work", "self_care"], tags: ["taoism", "useless", "useful", "tree", "zhuangzi", "efficiency", "endurance", "not_used_up"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Butterfly Dream — Zhuangzi's Paradox", tradition: "Taoism", source: "Zhuangzi 2 (Discussion on Making All Things Equal)", explanation: "Zhuangzi's famous dream: he dreamed he was a butterfly, and on waking, did not know whether he was Zhuangzi dreaming he was a butterfly, or a butterfly dreaming he was Zhuangzi. The teaching's precision: the distinction between self and other, between dream and waking, is not fixed — the dreamer and the dreamed are not two.", application: "Use the butterfly dream as the library's identity teaching: the self's boundaries are not fixed. The application is the boundary's recognition — where is the self's 'Zhuangzi' and where is its 'butterfly'? The recognition is the boundary's softening.", questions: ["Where is my identity fixed — and what would softening it look like?", "What is the difference between the dreamer and the dreamed?", "Can I hold the not-knowing — not as confusion but as accuracy?"], references: ["Zhuangzi 2 (Discussion on Making All Things Equal)", "Zhuangzi 17", "Tao Te Ching 1"], excerpt: "Zhuangzi dreamed he was a butterfly. On waking, he did not know which was which.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "spirituality", "growth"], tags: ["taoism", "butterfly", "dream", "zhuangzi", "identity", "boundary", "not_knowing"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Relativity of All Things — Making All Things Equal", tradition: "Taoism", source: "Zhuangzi 2 (Discussion on Making All Things Equal)", explanation: "Zhuangzi's central teaching: things are not absolutely right or wrong, large or small, beautiful or ugly — the distinctions are relative, perspectival, and the sage sees through them. The teaching's precision: not that all things are equal in value but that the distinctions are made, not found — and the sage sees the making.", application: "Use the relativity teaching as the library's perspective practice: in any judgment, ask 'from what perspective?' The application is the perspective's recognition — not the judgment's abandonment but its contextualization. The library's pluralism entries inherit this.", questions: ["What is my current judgment — and from what perspective?", "Where are the distinctions made, not found?", "Can I hold a distinction as made — not as found — without losing its usefulness?"], references: ["Zhuangzi 2 (Discussion on Making All Things Equal)", "Zhuangzi 17", "Tao Te Ching 2"], excerpt: "Things are not absolutely right or wrong — the distinctions are made, not found.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "growth"], tags: ["taoism", "relativity", "zhuangzi", "perspective", "distinctions", "made", "equal"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Pivot of the Tao — The Center", tradition: "Taoism", source: "Zhuangzi 2 (Discussion on Making All Things Equal)", explanation: "Zhuangzi's image: the pivot of the Tao — the center from which all perspectives are seen. The teaching's precision: the pivot is not a viewpoint among viewpoints but the axis around which all viewpoints turn. The sage rests at the pivot, seeing all perspectives without being any of them.", application: "Use the pivot as the library's non-identification teaching: in any debate, rest at the pivot — not as a compromise but as the axis. The application is the axis's recognition — the pivot is not a position but the space in which positions turn.", questions: ["Where is my current pivot — and am I resting at it?", "What is the difference between the pivot (axis) and a position (viewpoint)?", "Can I see all perspectives without being any of them?"], references: ["Zhuangzi 2 (Discussion on Making All Things Equal)", "Zhuangzi 17", "Tao Te Ching 14"], excerpt: "The pivot of the Tao — the center from which all perspectives are seen.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "growth"], tags: ["taoism", "pivot", "center", "axis", "perspectives", "zhuangzi", "non_identification"], difficulty: "advanced", minutes: 8 },
  { concept: "The Sage's Three Treasures in Action", tradition: "Taoism", source: "Tao Te Ching 67; Zhuangzi 7", explanation: "The Tao Te Ching's three treasures — compassion, frugality, humility — in their practical application. The teaching's precision: compassion without compassion's performance, frugality without frugality's display, humility without humility's announcement. The sage's treasures are invisible because they are not performed.", application: "Use the three treasures' invisibility as the library's authenticity teaching: the practice's fruit is not displayed but lived. The application is the display's release — not the treasure's abandonment but its privatization.", questions: ["Where is my practice's display — and what is its cost?", "What is the difference between the treasure and its performance?", "Can I practice without display — and is that the treasure's completion?"], references: ["Tao Te Ching 67", "Zhuangzi 7 (Fit for Emperors and Kings)", "Tao Te Ching 58"], excerpt: "Compassion, frugality, humility — invisible because not performed.", evidence: "traditional", dimensions: ["action", "emotion", "spirit"], paths: ["tao", "karma"], domains: ["growth", "work", "relationships"], tags: ["taoism", "three_treasures", "invisible", "authenticity", "display", "performance", "practice"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Cook Ding — The Perfect Cut", tradition: "Taoism", source: "Zhuangzi 3 (Essentials for Nurturing Life)", explanation: "Zhuangzi's famous story of Cook Ding, who carved oxen so perfectly that his knife never dulled — he followed the natural joints, the spaces between, rather than forcing through the bones. The teaching's precision: skill is not force but alignment — the cook follows the ox's structure, not his own will.", application: "Use Cook Ding as the library's skill-teaching: in the next task, follow the joints, not the bones. The application is the forcing's release — the work is easier when it follows the material's structure, not the worker's will.", questions: ["Where am I cutting through bones instead of following joints?", "What is the structure I am working with — and how do I find it?", "Can I work with the material's grain, not against it?"], references: ["Zhuangzi 3 (Essentials for Nurturing Life)", "Zhuangzi 19", "Tao Te Ching 37"], excerpt: "Cook Ding followed the natural joints. His knife never dulled.", evidence: "traditional", dimensions: ["action", "thought", "body"], paths: ["tao", "karma"], domains: ["work", "growth", "learning"], tags: ["taoism", "cook_ding", "skill", "joints", "knife", "alignment", "structure", "force"], difficulty: "beginner", minutes: 7 },
  { concept: "The Woodcarver Qing — The Right Conditions", tradition: "Taoism", source: "Zhuangzi 19 (Mastering Life)", explanation: "Zhuangzi's story of the woodcarver Qing, who carved a bell-stand so perfect that all thought it was the work of spirits. Asked his secret, he said: he fasted to quiet his mind, found the right tree, and let the wood's nature guide his hands. The teaching's precision: mastery is not technique but the alignment of conditions — the right mind, the right material, the right moment.", application: "Use the woodcarver as the library's mastery-teaching: the perfect work requires the right conditions — not just skill but preparation, material, and timing. The application is the conditions' cultivation — the practice is not the work but the conditions' preparation.", questions: ["What are my current conditions — and which are missing?", "Where is my practice ahead of its conditions?", "Can I cultivate the conditions and let the work follow?"], references: ["Zhuangzi 19 (Mastering Life)", "Zhuangzi 3", "Tao Te Ching 37"], excerpt: "The woodcarver found the right tree, quieted his mind, and let the wood guide his hands.", evidence: "traditional", dimensions: ["action", "thought", "body"], paths: ["tao", "karma"], domains: ["work", "growth", "learning"], tags: ["taoism", "woodcarver", "qing", "conditions", "mastery", "timing", "preparation", "alignment"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Tao of the Body — The Body's Wisdom", tradition: "Taoism", source: "Tao Te Ching 51-52; Zhuangzi 10", explanation: "The Tao Te Ching's teaching: the Tao gives birth to all things, nourishes them, completes them. The teaching's precision: the body's wisdom is not the mind's instruction but the Tao's nourishment — the body knows its own way, if the mind does not interfere. The Tao of the body is the body's self-organizing intelligence.", application: "Use the body's Tao as the library's somatic foundation: the body has its own wisdom — the practice is not to impose the mind's wisdom but to follow the body's. The application is the interference's recognition — where is the mind interfering with the body's Tao?", questions: ["Where is my mind interfering with my body's wisdom?", "What is the body's self-organizing intelligence — and how do I access it?", "Can I follow the body's Tao without the mind's override?"], references: ["Tao Te Ching 51-52", "Zhuangzi 10 (Ransacking Coffers)", "Tao Te Ching 10"], excerpt: "The Tao gives birth, nourishes, completes. The body's wisdom is the Tao's nourishment.", evidence: "traditional", dimensions: ["body", "spirit", "thought"], paths: ["tao", "hatha"], domains: ["health", "growth"], tags: ["taoism", "body", "wisdom", "self_organizing", "nourishment", "interference", "tao"], difficulty: "beginner", minutes: 6 },
  { concept: "The Tao of Breathing — The Infant's Breath", tradition: "Taoism", source: "Tao Te Ching 10, 55", explanation: "The Tao Te Ching's teaching: the infant's breath is deep — the baby breathes from the belly, the whole body participates, the breath is natural and unforced. The adult's breath is shallow — the mind's interference has shortened it. The teaching's precision: the Tao of breathing is the return to the infant's breath — not the technique's addition but the mind's release.", application: "Use the infant's breath as the library's breath foundation: the breath's goal is not a technique but the release of the mind's interference. The application is the interference's recognition — where is the mind shortening the breath? The release is the breath's natural depth.", questions: ["Where is my mind interfering with my breath?", "What is the infant's breath — and how do I return to it?", "Can I release the interference and let the breath deepen?"], references: ["Tao Te Ching 10", "Tao Te Ching 55", "Zhuangzi 19"], excerpt: "The infant's breath is deep. The adult's breath is shallow — the mind's interference has shortened it.", evidence: "traditional", dimensions: ["body", "thought", "spirit"], paths: ["tao", "hatha"], domains: ["health", "learning"], tags: ["taoism", "breath", "infant", "deep", "interference", "release", "natural"], difficulty: "beginner", minutes: 6 },
  { concept: "The Tao of Walking — The Walking Without Arriving", tradition: "Taoism", source: "Tao Te Ching 27, 47; Zhuangzi 6", explanation: "The Tao Te Ching's teaching: without leaving the door, you know the world; without looking out the window, you see the Tao of heaven. The teaching's precision: the walking is not the traveling — the arrival is not the destination. The Tao is not found by going but by being where you are.", application: "Use the walking teaching as the library's presence practice: the next walk is not toward a destination but the practice itself. The application is the arrival's release — the walk is the destination; the destination is the walk.", questions: ["Where am I walking toward — and what is the arrival's cost?", "What is the difference between walking (the practice) and arriving (the goal)?", "Can I walk without arriving — and is that the walking's completion?"], references: ["Tao Te Ching 27", "Tao Te Ching 47", "Zhuangzi 6"], excerpt: "Without leaving the door, you know the world. The walking is the destination.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["tao", "raja"], domains: ["growth", "self_care", "learning"], tags: ["taoism", "walking", "arrival", "door", "presence", "destination", "practice"], difficulty: "beginner", minutes: 6 },
  { concept: "The Sage's Emptiness — The Mirror Mind", tradition: "Taoism", source: "Zhuangzi 7 (Fit for Emperors and Kings)", explanation: "Zhuangzi's teaching on the sage's mind: the sage's mind is a mirror — it receives without storing, reflects without retaining, responds without clinging. The teaching's precision: the mirror mind is not empty (blank) but clear — it receives all, retains nothing. The sage's mind is the world's mirror, not the world's warehouse.", application: "Use the mirror mind as the library's attention teaching: the next experience is received, not stored. The application is the storing's release — the experience is received, the experience passes, the mind is clear. The mirror does not remember; it reflects.", questions: ["Where is my mind storing what it should be reflecting?", "What is the difference between the mirror (receiving) and the warehouse (storing)?", "Can I receive the next experience without storing it?"], references: ["Zhuangzi 7 (Fit for Emperors and Kings)", "Tao Te Ching 14", "Zhuangzi 2"], excerpt: "The sage's mind is a mirror — it receives without storing, reflects without retaining.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["tao", "jnana"], domains: ["learning", "growth"], tags: ["taoism", "sage", "mirror", "empty", "clear", "receiving", "storing", "zhuangzi"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Tao of Sleep — The Body's Natural Return", tradition: "Taoism", source: "Tao Te Ching 10, 55; Zhuangzi 18", explanation: "The Tao Te Ching's teaching: sleep is the body's natural return to the Tao — the body, unmanaged by the mind, returns to its source. The teaching's precision: sleep is not the mind's cessation but the mind's release — the body, freed from the mind's interference, returns to its Tao. The mind's interference is the obstacle to sleep, not the absence of technique.", application: "Use the Tao of sleep as the library's sleep foundation: the sleep practice is not the mind's management but its release. The application is the interference's recognition — where is the mind interfering with sleep? The release is the sleep's natural arrival.", questions: ["Where is my mind interfering with sleep?", "What is the difference between managing sleep and releasing into it?", "Can I release the mind's interference and let sleep arrive?"], references: ["Tao Te Ching 10", "Tao Te Ching 55", "Zhuangzi 18 (Perfect Joy)"], excerpt: "Sleep is the body's natural return to the Tao — the mind's release, not its management.", evidence: "traditional", dimensions: ["body", "spirit", "thought"], paths: ["tao", "hatha"], domains: ["rest", "health"], tags: ["taoism", "sleep", "return", "tao", "mind", "interference", "release", "natural"], difficulty: "beginner", minutes: 6 },
  { concept: "The Tao Te Ching's Closing — The Sage's Way", tradition: "Taoism", source: "Tao Te Ching 81", explanation: "The Tao Te Ching's final chapter: the sage does not hoard; the more he gives to others, the more he has; the more he expends, the more he gains. The teaching's precision: the sage's way is the opposite of the accumulator's — the giver's wealth increases, the hoarder's decreases. The closing is the text's final paradox and its final teaching.", application: "Use the closing as the library's generosity teaching: the practice's fruit is not accumulated but given. The application is the hoarding's release — not the practice's abandonment but the fruit's circulation. The library's knowledge graph embodies this: entries are shared, not hoarded.", questions: ["Where is my practice hoarding — and what is the hoarding's cost?", "What is the difference between accumulating and giving?", "Can I circulate the practice's fruit — and is that the practice's completion?"], references: ["Tao Te Ching 81", "Tao Te Ching 67", "Zhuangzi 7"], excerpt: "The sage does not hoard; the more he gives, the more he has.", evidence: "traditional", dimensions: ["action", "spirit", "connection"], paths: ["tao", "karma"], domains: ["growth", "community", "relationships"], tags: ["taoism", "tao_te_ching", "closing", "sage", "giving", "hoarding", "generosity", "wealth"], difficulty: "intermediate", minutes: 7 },
];

export const WISDOM_STOICISM: WisdomArchetype[] = [
  { concept: "The Dichotomy of Control", tradition: "Stoicism", source: "Epictetus, Enchiridion 1", explanation: "Epictetus's foundational teaching: some things are in our control (judgments, impulses, desires, aversions) and some are not (body, property, reputation, office). The teaching's precision: the distinction is not advice but ontology — what is yours and what is not. Suffering arises from confusing the two.", application: "Use the dichotomy as the library's daily filter: in any situation, ask 'is this in my control?' If yes, act; if no, accept. The application is the confusion's recognition — where am I treating the uncontrollable as controllable?", questions: ["What am I treating as controllable that is not?", "What am I treating as uncontrollable that is?", "Can I act on the controllable and accept the rest?"], references: ["Epictetus, Enchiridion 1", "Epictetus, Discourses 2.5", "Marcus Aurelius, Meditations 2.1"], excerpt: "Some things are in our control; some are not. The distinction is the whole teaching.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["stoic", "karma"], domains: ["growth", "work", "relationships"], tags: ["stoicism", "dichotomy_of_control", "epictetus", "control", "acceptance", "filter"], difficulty: "beginner", minutes: 6 },
  { concept: "The View from Above — Cosmic Perspective", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 7.48, 9.30, 12.24", explanation: "Marcus Aurelius's practice: view things from above — the earth as a point, the cities as ant-hills, the crowds as swarming ants. The teaching's precision: the perspective is not contempt but scale — the cosmic view dissolves the personal's inflation. The practice is the view's regular taking, not its occasional use.", application: "Use the view from above as the library's perspective practice: in any crisis, take the cosmic view. The application is the inflation's release — the personal's urgency, seen from above, becomes proportionate. The practice is the regularity, not the intensity.", questions: ["Where is my perspective inflated — and what would the cosmic view change?", "What is the difference between the view from above and contempt?", "Can I take the view regularly — not just in crisis?"], references: ["Marcus Aurelius, Meditations 7.48", "Marcus Aurelius, Meditations 9.30", "Marcus Aurelius, Meditations 12.24"], excerpt: "View things from above: the earth is a point, the cities are ant-hills.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["stoic", "jnana"], domains: ["growth", "work"], tags: ["stoicism", "view_from_above", "marcus_aurelius", "cosmic", "perspective", "scale", "inflation"], difficulty: "beginner", minutes: 6 },
  { concept: "The Inner Citadel — The Invulnerable Self", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 8.48, 12.3", explanation: "Marcus Aurelius's image: the inner citadel — the mind's fortress, invulnerable to external assault. The teaching's precision: the citadel is not the body's defense but the mind's — the externals cannot enter unless the mind admits them. The citadel is the practice's goal, not its starting point.", application: "Use the inner citadel as the library's invulnerability teaching: the mind's fortress is built not by walling the world but by not admitting the assault. The application is the admission's recognition — where is the mind admitting what it could refuse?", questions: ["Where is my mind admitting what it could refuse?", "What is the difference between the citadel (mind) and the wall (body)?", "Can I build the citadel — not by walling but by refusing admission?"], references: ["Marcus Aurelius, Meditations 8.48", "Marcus Aurelius, Meditations 12.3", "Epictetus, Discourses 4.4"], excerpt: "The inner citadel — the mind's fortress, invulnerable to external assault.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["stoic", "raja"], domains: ["growth", "work", "self_care"], tags: ["stoicism", "inner_citadel", "marcus_aurelius", "fortress", "invulnerable", "mind", "admission"], difficulty: "intermediate", minutes: 7 },
  { concept: "Amor Fati — Love of Fate", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 7.57; Nietzsche's phrase, Stoic root", explanation: "The Stoic root of amor fati: the acceptance — no, the love — of what happens. Marcus Aurelius: accept what happens, because it was meant to happen. The teaching's precision: not resignation (enduring) but love (embracing). The fate is not endured but loved — the distinction is the whole teaching.", application: "Use amor fati as the library's acceptance teaching: in the next adverse event, do not endure — love. The application is the love's recognition — where is the endurance (gritting teeth) and where is the love (embracing)? The practice is the love's cultivation.", questions: ["Where am I enduring instead of loving?", "What is the difference between amor fati (love) and resignation (endurance)?", "Can I love what has happened — and what is happening?"], references: ["Marcus Aurelius, Meditations 7.57", "Marcus Aurelius, Meditations 8.15", "Epictetus, Enchiridion 5"], excerpt: "Accept what happens, because it was meant to happen. Not endurance — love.", evidence: "traditional", dimensions: ["emotion", "thought", "spirit"], paths: ["stoic", "bhakti"], domains: ["growth", "spirituality"], tags: ["stoicism", "amor_fati", "love_of_fate", "acceptance", "marcus_aurelius", "resignation", "love"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Discipline of Assent — Sunkatathesis", tradition: "Stoicism", source: "Epictetus, Discourses 1.6, 3.12", explanation: "Epictetus's three disciplines: assent (sunkatathesis), desire (orexis), and action (horme). The discipline of assent: the mind's approval of an impression — not every impression is true, and the sage withholds assent until the impression is tested. The teaching's precision: the assent is the mind's active choice, not the impression's passive reception.", application: "Use the discipline of assent as the library's cognitive teaching: in the next impression ('this is terrible'), withhold assent. The application is the withholding's practice — not denial but examination. The impression is tested before it is believed.", questions: ["Where is my assent automatic — and what is its cost?", "What is the difference between receiving an impression and assenting to it?", "Can I withhold assent for one impression today — and examine it?"], references: ["Epictetus, Discourses 1.6", "Epictetus, Discourses 3.12", "Marcus Aurelius, Meditations 8.49"], excerpt: "The mind's assent is active, not passive. Withhold it until the impression is tested.", evidence: "traditional", dimensions: ["thought", "action"], paths: ["stoic", "raja"], domains: ["growth", "work"], tags: ["stoicism", "assent", "sunkatathesis", "epictetus", "impression", "withholding", "examination"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Discipline of Desire — Orexis", tradition: "Stoicism", source: "Epictetus, Discourses 3.2, 3.24", explanation: "The second discipline: desire (orexis) — the sage desires only what is in his control (virtue, the good) and does not desire what is not (externals). The teaching's precision: desire is not eliminated but redirected — from the external (which is not yours) to the internal (which is). The redirection is the discipline.", application: "Use the discipline of desire as the library's redirection teaching: in the next desire, ask 'is this in my control?' If yes, desire it; if no, do not. The application is the desire's audit — what am I desiring that is not mine to desire?", questions: ["What am I desiring that is not in my control?", "What is the difference between eliminating desire and redirecting it?", "Can I desire the good — and only the good?"], references: ["Epictetus, Discourses 3.2", "Epictetus, Discourses 3.24", "Marcus Aurelius, Meditations 12.1"], excerpt: "Desire only what is in your control. Redirect the desire from the external to the internal.", evidence: "traditional", dimensions: ["emotion", "thought", "action"], paths: ["stoic", "karma"], domains: ["growth", "health"], tags: ["stoicism", "desire", "orexis", "epictetus", "redirection", "control", "internal", "external"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Discipline of Action — Horme", tradition: "Stoicism", source: "Epictetus, Discourses 3.24, 4.4", explanation: "The third discipline: action (horme) — the sage acts toward what is in his control, with reservation (hypexairesis) — the action is committed, the result is released. The teaching's precision: the action is fully engaged, the result is fully released. The reservation is not half-measure but whole-measure: full effort, zero claim.", application: "Use the discipline of action as the library's karma-yoga entry: in the next action, engage fully and release the result. The application is the reservation's practice — the action is complete, the result is not the actor's.", questions: ["Where is my action half-engaged — and where is it half-released?", "What is the difference between reservation and half-measure?", "Can I act fully while releasing the result fully?"], references: ["Epictetus, Discourses 3.24", "Epictetus, Discourses 4.4", "Marcus Aurelius, Meditations 9.29"], excerpt: "Act with reservation — full effort, zero claim on the result.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["stoic", "karma"], domains: ["work", "growth"], tags: ["stoicism", "action", "horme", "epictetus", "reservation", "hypexairesis", "full_effort", "zero_claim"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Reserve Clause — Hypexairesis", tradition: "Stoicism", source: "Epictetus, Discourses 2.6, 4.1", explanation: "The Stoic reserve clause: 'I will do this, if nothing prevents me' — every intention carries an implicit 'if the gods will'. The teaching's precision: the clause is not hedging but accuracy — the result is not in the actor's control, and the clause acknowledges it. The action is committed; the result is reserved.", application: "Use the reserve clause as the library's intention practice: before any action, add the clause — 'I will do this, if nothing prevents.' The application is the clause's honesty — the action is full, the result is not claimed.", questions: ["What is my current intention without the reserve clause — and what is its cost?", "What is the difference between the clause and hedging?", "Can I commit fully while reserving the result?"], references: ["Epictetus, Discourses 2.6", "Epictetus, Discourses 4.1", "Marcus Aurelius, Meditations 5.20"], excerpt: "I will do this, if nothing prevents me. The action is committed; the result is reserved.", evidence: "traditional", dimensions: ["action", "thought"], paths: ["stoic", "karma"], domains: ["work", "growth"], tags: ["stoicism", "reserve_clause", "hypexairesis", "epictetus", "intention", "commitment", "result"], difficulty: "intermediate", minutes: 6 },
  { concept: "The Indifferents — Preferred and Dispreferred", tradition: "Stoicism", source: "Epictetus, Discourses 2.5, 2.6; Diogenes Laertius", explanation: "The Stoic teaching on indifferents (adiaphora): health, wealth, reputation are neither good nor bad — they are preferred indifferents (proegmena). The teaching's precision: the indifferents are not valueless but not good — they are preferred (selected when possible) but not pursued (as if good). The distinction is the Stoic's daily practice.", application: "Use the indifferents as the library's valuation teaching: in the next choice, ask 'is this good or preferred?' The application is the preference's discipline — select the preferred, do not pursue the good. The distinction is the practice's core.", questions: ["What am I treating as good that is merely preferred?", "What is the difference between preferring and pursuing?", "Can I select the preferred without pursuing it as the good?"], references: ["Epictetus, Discourses 2.5", "Epictetus, Discourses 2.6", "Diogenes Laertius 7.102-105"], excerpt: "Health, wealth, reputation are preferred indifferents — selected, not pursued.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["stoic", "karma"], domains: ["growth", "work", "health"], tags: ["stoicism", "indifferents", "adiaphora", "preferred", "proegmena", "valuation", "selection"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Sage — The Stoic Ideal", tradition: "Stoicism", source: "Diogenes Laertius 7.89; Seneca, Letters 41", explanation: "The Stoic sage — the ideal human: wise, virtuous, undisturbed by externals, in harmony with nature. The teaching's precision: the sage is not a superhuman but the human at its full development — the teaching's horizon, not its starting point. The sage's features: equanimity, self-sufficiency, cosmopolitanism, virtue as the only good.", application: "Use the sage as the library's horizon teaching: the sage is the direction, not the destination. The application is the direction's honesty — not the sage's imitation but the sage's direction. The library's progress entries inherit this: the horizon is the measure, not the achievement.", questions: ["What is the sage's direction — and where am I walking toward it?", "What is the difference between the sage (horizon) and the sage (destination)?", "Can I hold the sage as direction without demanding achievement?"], references: ["Diogenes Laertius 7.89", "Seneca, Letters 41", "Marcus Aurelius, Meditations 3.4"], excerpt: "The sage — the human at full development. The horizon, not the destination.", evidence: "traditional", dimensions: ["spirit", "thought", "action"], paths: ["stoic", "jnana"], domains: ["growth", "spirituality"], tags: ["stoicism", "sage", "ideal", "horizon", "equanimity", "self_sufficiency", "virtue"], difficulty: "intermediate", minutes: 7 },
  { concept: "Memento Mori — Remember You Must Die", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.48; 7.56; 12.36", explanation: "The Stoic practice of memento mori: remember you must die. Marcus Aurelius's daily contemplation of mortality — not morbid but clarifying. The teaching's precision: mortality is not a future event but a present fact; the contemplation's purpose is not fear but proportion — the urgency's restoration.", application: "Use memento mori as the library's mortality practice: in the next planning, remember the mortality. The application is the proportion's restoration — the urgent (trivial) becomes trivial, the important (trivial-by-habit) becomes urgent.", questions: ["Where is my planning urgent about the trivial and trivial about the important?", "What is the difference between memento mori (clarifying) and morbidity (paralyzing)?", "Can I remember mortality without fear — and with proportion?"], references: ["Marcus Aurelius, Meditations 4.48", "Marcus Aurelius, Meditations 7.56", "Marcus Aurelius, Meditations 12.36"], excerpt: "Remember you must die — not to fear, but to proportion.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["stoic", "jnana"], domains: ["growth", "purpose"], tags: ["stoicism", "memento_mori", "mortality", "marcus_aurelius", "proportion", "urgency", "clarifying"], difficulty: "beginner", minutes: 6 },
  { concept: "Premeditatio Malorum — The Premeditation of Evils", tradition: "Stoicism", source: "Seneca, Letters 91; Marcus Aurelius, Meditations", explanation: "Seneca's practice: premeditatio malorum — the premeditation of evils. Before any venture, contemplate the worst that could happen — loss, illness, death. The teaching's precision: the premeditation is not pessimism but preparation — the event, premeditated, loses its shock; the shock was the suffering, not the event.", application: "Use premeditatio malorum as the library's preparation practice: before the next venture, contemplate the worst. The application is the shock's release — the premeditated event is met with equanimity, not surprise.", questions: ["What am I entering unprepared — and what is the worst case?", "What is the difference between premeditation (preparation) and pessimism (expectation)?", "Can I premeditate the worst — and act anyway?"], references: ["Seneca, Letters 91", "Marcus Aurelius, Meditations (throughout)", "Epictetus, Discourses 3.13"], excerpt: "Premeditate the evils — not to expect them, but to be unshocked by them.", evidence: "traditional", dimensions: ["thought", "emotion", "action"], paths: ["stoic", "raja"], domains: ["growth", "work"], tags: ["stoicism", "premeditatio_malorum", "seneca", "preparation", "worst_case", "shock", "equanimity"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Evening Review — Seneca's Daily Audit", tradition: "Stoicism", source: "Seneca, On Anger 3.36; Letters 83", explanation: "Seneca's practice: the evening review — 'What bad habit did I cure today? What fault did I fight? In what respect am I better?' The teaching's precision: the review is not guilt's instrument but the day's completion — the day is reviewed, learned from, and released.", application: "Use the evening review as the library's daily closure: three questions — what cured, what fought, what better. The application is the day's completion — not rumination but review. The library's evening entries inherit this structure.", questions: ["What bad habit did I cure today?", "What fault did I fight?", "In what respect am I better — and what is the evidence?"], references: ["Seneca, On Anger 3.36", "Seneca, Letters 83", "Marcus Aurelius, Meditations (throughout)"], excerpt: "What bad habit did I cure today? What fault did I fight? In what respect am I better?", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["stoic", "raja"], domains: ["growth", "self_care"], tags: ["stoicism", "evening_review", "seneca", "daily_audit", "cure", "fault", "better"], difficulty: "beginner", minutes: 6 },
  { concept: "The Morning Preparation — Marcus's Daily Intention", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 2.1, 5.1", explanation: "Marcus Aurelius's morning practice: prepare for the day's challenges — the difficult people, the obstacles, the losses — before they arrive. The teaching's precision: the preparation is not pessimism but readiness — the day's difficulties are premeditated, and the premeditation is the preparation.", application: "Use the morning preparation as the library's daily opening: before the day's first input, prepare for its difficulties. The application is the readiness's cultivation — the day is met with preparation, not surprise.", questions: ["What difficulties am I likely to meet today — and how will I meet them?", "What is the difference between preparation and pessimism?", "Can I prepare without predicting — readiness without anxiety?"], references: ["Marcus Aurelius, Meditations 2.1", "Marcus Aurelius, Meditations 5.1", "Marcus Aurelius, Meditations 8.5"], excerpt: "Prepare for the day's difficulties — not pessimism, but readiness.", evidence: "traditional", dimensions: ["thought", "action", "emotion"], paths: ["stoic", "raja"], domains: ["growth", "work", "self_care"], tags: ["stoicism", "morning_preparation", "marcus_aurelius", "daily", "readiness", "difficulties"], difficulty: "beginner", minutes: 6 },
  { concept: "The Obstacle Is the Way — The Stoic Turn", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 5.20; Seneca, Letters 85", explanation: "The Stoic teaching: the obstacle is not the obstacle — the obstacle is the way. Marcus Aurelius: what stands in the way becomes the way. The teaching's precision: the obstacle is not removed but transformed — the impediment becomes the path. The teaching is not optimism but accuracy — the obstacle's nature is the path's material.", application: "Use the obstacle-as-way as the library's adversity teaching: in the next obstacle, do not remove — transform. The application is the transformation's recognition — the obstacle is not the enemy but the material. The library's challenge entries inherit this.", questions: ["What is my current obstacle — and what is its material?", "What is the difference between removing the obstacle and transforming it?", "Can I hold the obstacle as the way — not as optimism but as accuracy?"], references: ["Marcus Aurelius, Meditations 5.20", "Seneca, Letters 85", "Epictetus, Discourses 1.6"], excerpt: "What stands in the way becomes the way. The obstacle is the material.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["stoic", "karma"], domains: ["growth", "work"], tags: ["stoicism", "obstacle_is_the_way", "marcus_aurelius", "seneca", "transformation", "material", "adversity"], difficulty: "beginner", minutes: 6 },
  { concept: "The Universe as a City — Cosmopolitanism", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.4, 6.44, 12.26", explanation: "The Stoic teaching: the universe is a single city — the cosmos as polis. Marcus Aurelius: I am a citizen of the universe. The teaching's precision: the city is not a metaphor for human unity but the recognition that the cosmos is the only real city — all human cities are its districts.", application: "Use cosmopolitanism as the library's universalism teaching: in the next conflict, remember the cosmic city. The application is the scale's restoration — the conflict is between districts of one city. The library's connection entries inherit this.", questions: ["Where is my identity's city — and what is its scale?", "What is the difference between the cosmic city and human unity?", "Can I hold the cosmic city as real — not as metaphor but as recognition?"], references: ["Marcus Aurelius, Meditations 4.4", "Marcus Aurelius, Meditations 6.44", "Marcus Aurelius, Meditations 12.26"], excerpt: "I am a citizen of the universe. The cosmos is the only real city.", evidence: "traditional", dimensions: ["connection", "thought", "spirit"], paths: ["stoic", "bhakti"], domains: ["relationships", "community", "growth"], tags: ["stoicism", "cosmopolitanism", "marcus_aurelius", "cosmic_city", "universe", "districts", "universalism"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Logos — Universal Reason", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.40, 6.38; Seneca, Letters 94", explanation: "The Stoic teaching: the logos — universal reason, the divine principle that orders the cosmos. The teaching's precision: the logos is not a person but a principle — the rational order that governs all things, including the human mind. To live according to nature is to live according to the logos.", application: "Use the logos as the library's order teaching: the cosmos is rational — not in the human sense but in the sense of being ordered, lawful, intelligible. The application is the order's recognition — in any chaos, look for the logos's pattern.", questions: ["Where is the logos's pattern in my current chaos?", "What is the difference between human reason and universal reason?", "Can I live according to the logos — not as belief but as practice?"], references: ["Marcus Aurelius, Meditations 4.40", "Marcus Aurelius, Meditations 6.38", "Seneca, Letters 94"], excerpt: "The logos — universal reason, the principle that orders the cosmos.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["stoic", "jnana"], domains: ["learning", "spirituality"], tags: ["stoicism", "logos", "universal_reason", "order", "nature", "principle", "cosmos"], difficulty: "advanced", minutes: 8 },
  { concept: "The Stoic's God — Nature's Divine Fire", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.40, 6.38; Seneca, Letters 95", explanation: "The Stoic theology: God is the divine fire (pneuma) that pervades the cosmos, the active principle that gives form to passive matter. The teaching's precision: God is not a person but a process — the universe's rational fire, the source of all order. The Stoic's God is not prayed to but aligned with.", application: "Use the Stoic God as the library's alignment teaching: the divine is not above but within — the fire that orders the cosmos is the same fire that orders the mind. The application is the alignment's practice — live according to nature, which is the logos, which is the divine.", questions: ["Where is the divine fire in my current experience?", "What is the difference between the Stoic's God and the personal God?", "Can I align with the divine — not as belief but as practice?"], references: ["Marcus Aurelius, Meditations 4.40", "Marcus Aurelius, Meditations 6.38", "Seneca, Letters 95"], excerpt: "God is the divine fire — the active principle that orders the cosmos.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["stoic", "jnana"], domains: ["spirituality", "learning"], tags: ["stoicism", "god", "divine_fire", "pneuma", "process", "alignment", "nature"], difficulty: "advanced", minutes: 8 },
  { concept: "The Stoic's Death — Not to Be Feared", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.5, 6.24, 12.36", explanation: "The Stoic teaching on death: death is neither good nor bad — it is an indifferent, the body's natural dissolution. Marcus Aurelius: death is a natural process, not to be feared. The teaching's precision: the fear of death is the fear of the unknown, and the unknown is not the death but the mind's projection.", application: "Use the Stoic death teaching as the library's mortality practice: death is not to be feared, not because it is pleasant but because it is natural. The application is the fear's release — not the death's denial but the fear's examination.", questions: ["Where is my fear of death — and what is it actually fearing?", "What is the difference between the death (natural) and the fear (projected)?", "Can I hold death as natural — not as belief but as recognition?"], references: ["Marcus Aurelius, Meditations 4.5", "Marcus Aurelius, Meditations 6.24", "Marcus Aurelius, Meditations 12.36"], excerpt: "Death is a natural process, not to be feared. The fear is the projection, not the death.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["stoic", "jnana"], domains: ["growth", "spirituality"], tags: ["stoicism", "death", "mortality", "marcus_aurelius", "natural", "fear", "projection"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Anger — Seneca's Cure", tradition: "Stoicism", source: "Seneca, On Anger (De Ira) 1-3", explanation: "Seneca's treatise on anger: anger is the most destructive passion — not because it is powerful but because it is useless. The teaching's precision: anger is not a tool (it cannot be controlled once aroused) and not a virtue (it does not correct). The cure is prevention — the mind's assent is withheld from the impression that triggers anger.", application: "Use Seneca's anger teaching as the library's regulation practice: anger is not managed but prevented — the assent is withheld. The application is the withholding's practice — not the anger's suppression but the impression's examination.", questions: ["Where is my anger's impression — and what is its trigger?", "What is the difference between anger (useless) and indignation (useful)?", "Can I withhold assent from the triggering impression — and prevent the anger?"], references: ["Seneca, On Anger (De Ira) 1-3", "Seneca, On Anger 2.1-2.3", "Seneca, On Anger 3.1-3.3"], excerpt: "Anger is the most destructive passion — not powerful but useless. The cure is prevention.", evidence: "traditional", dimensions: ["emotion", "thought", "action"], paths: ["stoic", "raja"], domains: ["growth", "relationships", "health"], tags: ["stoicism", "anger", "seneca", "de_ira", "useless", "prevention", "assent", "withholding"], difficulty: "beginner", minutes: 7 },
  { concept: "The Stoic's Grief — Seneca's Consolation", tradition: "Stoicism", source: "Seneca, Consolation to Marcia; Letters 63, 99", explanation: "Seneca's consolations: grief is natural but not to be indulged. The teaching's precision: the sage grieves (he is human) but does not grieve as the unwise — the grief is felt, not amplified. The consolations' method: the grief's premeditation, the death's acceptance, the tears' permission, the grief's limit.", application: "Use the consolation as the library's grief practice: grieve — fully, briefly — and then release. The application is the grief's containment — not suppression but limit. The library's emotional-experience entries inherit this.", questions: ["Where is my grief — and is it felt or amplified?", "What is the difference between grief (felt) and indulgence (amplified)?", "Can I grieve fully — and then release?"], references: ["Seneca, Consolation to Marcia", "Seneca, Letters 63", "Seneca, Letters 99"], excerpt: "Grieve — fully, briefly — and then release. The grief is felt, not amplified.", evidence: "traditional", dimensions: ["emotion", "thought", "spirit"], paths: ["stoic", "bhakti"], domains: ["growth", "health", "relationships"], tags: ["stoicism", "grief", "seneca", "consolation", "felt", "amplified", "limit", "release"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Joy — The Joy of Virtue", tradition: "Stoicism", source: "Seneca, Letters 23, 74; Epictetus, Discourses 3.24", explanation: "The Stoic teaching: joy (gaudium) is the sage's emotion — the joy that accompanies virtue, the joy of alignment with nature. The teaching's precision: the joy is not pleasure (which is indifferent) but the byproduct of virtue — the soul's satisfaction in its own goodness. The joy is not pursued but consequent.", application: "Use the Stoic joy as the library's positive-psychology entry: the practice's joy is not the goal but the byproduct. The application is the joy's recognition — not the pursuit of pleasure but the cultivation of virtue, whose joy follows.", questions: ["Where is my joy — and is it pleasure or virtue's byproduct?", "What is the difference between pleasure (indifferent) and joy (consequent)?", "Can I cultivate virtue — and let joy follow?"], references: ["Seneca, Letters 23", "Seneca, Letters 74", "Epictetus, Discourses 3.24"], excerpt: "Joy is virtue's byproduct — not pursued but consequent.", evidence: "traditional", dimensions: ["emotion", "action", "spirit"], paths: ["stoic", "karma"], domains: ["growth", "self_care", "health"], tags: ["stoicism", "joy", "gaudium", "virtue", "byproduct", "consequent", "pleasure", "indifferent"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Fear — The Fear of the Unknown", tradition: "Stoicism", source: "Seneca, Letters 101; Marcus Aurelius, Meditations 2.14", explanation: "The Stoic teaching on fear: fear is not of the thing but of the anticipation. Seneca: we suffer more often in imagination than in reality. The teaching's precision: the fear's object is rarely the present — it is the future, the imagined. The cure is the present's return — the fear is dissolved by the actual.", application: "Use the fear teaching as the library's anxiety practice: when fear arises, ask 'is this the actual or the imagined?' The application is the present's return — the fear's dissolution is not its argument but its location in the present.", questions: ["Where is my fear — in the actual or the imagined?", "What is the difference between the fear (real) and its object (often imaginary)?", "Can I return to the present — and let the fear dissolve?"], references: ["Seneca, Letters 101", "Marcus Aurelius, Meditations 2.14", "Epictetus, Discourses 3.13"], excerpt: "We suffer more often in imagination than in reality. Fear is of the anticipated, not the actual.", evidence: "traditional", dimensions: ["emotion", "thought"], paths: ["stoic", "raja"], domains: ["health", "growth"], tags: ["stoicism", "fear", "seneca", "imagination", "reality", "anticipation", "present", "anxiety"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's Disturbance — The Mind's Assent", tradition: "Stoicism", source: "Epictetus, Enchiridion 5; Discourses 1.6", explanation: "Epictetus's core teaching: it is not the events that disturb people but their judgments about them. The teaching's precision: the event is neutral; the judgment is the disturbance's source. The disturbance is not in the world but in the assent — the mind's approval of the judgment.", application: "Use the disturbance teaching as the library's core cognitive practice: in any disturbance, separate the event (neutral) from the judgment (disturbing). The application is the separation's practice — not the event's change but the judgment's examination.", questions: ["Where is my disturbance — in the event or in the judgment?", "What is the difference between the event (neutral) and the judgment (disturbing)?", "Can I separate the two — and examine the judgment?"], references: ["Epictetus, Enchiridion 5", "Epictetus, Discourses 1.6", "Marcus Aurelius, Meditations 8.49"], excerpt: "It is not events that disturb people, but their judgments about them.", evidence: "traditional", dimensions: ["thought", "emotion"], paths: ["stoic", "jnana"], domains: ["growth", "learning"], tags: ["stoicism", "disturbance", "epictetus", "judgment", "event", "assent", "separation", "examination"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's Virtue — The Only Good", tradition: "Stoicism", source: "Epictetus, Discourses 1.29, 2.11; Diogenes Laertius 7.94", explanation: "The Stoic teaching: virtue is the only good. The teaching's precision: health, wealth, reputation are indifferents — neither good nor bad. Only virtue (wisdom, courage, justice, temperance) is good; only vice is bad. The teaching's radical claim: the good is entirely in the mind's state, not in the world's state.", application: "Use the virtue-only-good as the library's valuation teaching: in any evaluation, ask 'is this good or indifferent?' The application is the valuation's accuracy — not the world's change but the mind's reclassification. The library's ethics entries inherit this.", questions: ["What am I calling 'good' that is merely indifferent?", "What is the difference between the good (virtue) and the preferred (indifferent)?", "Can I reclassify my valuations — and live by the reclassification?"], references: ["Epictetus, Discourses 1.29", "Epictetus, Discourses 2.11", "Diogenes Laertius 7.94"], excerpt: "Virtue is the only good. Health, wealth, reputation are indifferents.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["stoic", "karma"], domains: ["ethics", "growth"], tags: ["stoicism", "virtue", "only_good", "indifferents", "wisdom", "courage", "justice", "temperance"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Community — The Cosmopolis", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.4, 6.44, 12.26", explanation: "The Stoic teaching: the cosmopolis — the cosmic city, in which all humans are fellow citizens. The teaching's precision: the cosmopolis is not a political program but a metaphysical fact — the universe is one city, and all humans are its citizens. The Stoic's loyalty is to the cosmopolis, not to any particular city.", application: "Use the cosmopolis as the library's universalism teaching: in any conflict, remember the cosmic city. The application is the scale's restoration — the conflict is between districts of one city. The library's connection entries inherit this.", questions: ["Where is my identity's city — and what is its scale?", "What is the difference between the cosmic city and human unity?", "Can I hold the cosmic city as real — not as metaphor but as recognition?"], references: ["Marcus Aurelius, Meditations 4.4", "Marcus Aurelius, Meditations 6.44", "Marcus Aurelius, Meditations 12.26"], excerpt: "I am a citizen of the universe. The cosmos is the only real city.", evidence: "traditional", dimensions: ["connection", "thought", "spirit"], paths: ["stoic", "bhakti"], domains: ["relationships", "community", "growth"], tags: ["stoicism", "cosmopolis", "cosmic_city", "marcus_aurelius", "universalism", "citizen", "districts"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Progress — The Prokope", tradition: "Stoicism", source: "Epictetus, Discourses 1.4; 2.11", explanation: "The Stoic teaching on progress (prokope): progress is not the achievement of the sage's state but the movement toward it. The teaching's precision: the prokope is the daily, incremental movement — the mind's gradual alignment with nature. The progress is measured not by states achieved but by obstacles removed.", application: "Use prokope as the library's progress teaching: progress is not a state but a movement. The application is the movement's recognition — not 'am I the sage?' but 'am I moving toward the sage?' The library's progress entries inherit this.", questions: ["Where is my progress — and is it a state or a movement?", "What is the difference between the sage (destination) and the prokope (movement)?", "Can I hold progress as movement — and measure it by obstacles removed?"], references: ["Epictetus, Discourses 1.4", "Epictetus, Discourses 2.11", "Seneca, Letters 75"], excerpt: "Progress is the movement toward the sage — measured by obstacles removed, not states achieved.", evidence: "traditional", dimensions: ["thought", "action", "spirit"], paths: ["stoic", "jnana"], domains: ["growth", "learning"], tags: ["stoicism", "prokope", "progress", "movement", "obstacles", "sage", "destination", "measure"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Consistency — The Inner Harmony", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 2.1, 4.3, 7.28", explanation: "The Stoic teaching: the inner harmony — the consistency of the mind's judgments, desires, and actions. Marcus Aurelius: the mind's disturbance is the inconsistency — wanting what is not yours, judging what is not true, acting against nature. The teaching's precision: harmony is not the absence of conflict but the alignment of the mind's parts.", application: "Use the inner harmony as the library's integrity teaching: in any conflict, check the mind's alignment — are the judgments, desires, and actions consistent? The application is the inconsistency's recognition — the disturbance is the misalignment, not the event.", questions: ["Where is my mind's inconsistency — judgment, desire, action?", "What is the difference between the event (external) and the misalignment (internal)?", "Can I align the mind's parts — and find the harmony?"], references: ["Marcus Aurelius, Meditations 2.1", "Marcus Aurelius, Meditations 4.3", "Marcus Aurelius, Meditations 7.28"], excerpt: "The mind's disturbance is the inconsistency. Harmony is the alignment of judgment, desire, and action.", evidence: "traditional", dimensions: ["thought", "emotion", "action"], paths: ["stoic", "raja"], domains: ["growth", "work", "self_care"], tags: ["stoicism", "harmony", "consistency", "marcus_aurelius", "alignment", "judgment", "desire", "action"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Acceptance — The Amor Fati's Root", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 8.15, 12.14; Epictetus, Enchiridion 8", explanation: "The Stoic teaching: acceptance — the root of amor fati. Epictetus: do not seek for things to happen as you wish, but wish for things to happen as they do happen. The teaching's precision: the acceptance is not passive but active — the wish is aligned with the event, not the event with the wish.", application: "Use the acceptance as the library's alignment practice: in any event, align the wish with the event. The application is the wish's release — not the event's change but the wish's transformation. The library's acceptance entries inherit this.", questions: ["Where is my wish opposing the event — and what is the cost?", "What is the difference between acceptance (alignment) and resignation (endurance)?", "Can I wish for things to happen as they do happen?"], references: ["Epictetus, Enchiridion 8", "Marcus Aurelius, Meditations 8.15", "Marcus Aurelius, Meditations 12.14"], excerpt: "Do not seek for things to happen as you wish — wish for things to happen as they do happen.", evidence: "traditional", dimensions: ["emotion", "thought", "spirit"], paths: ["stoic", "bhakti"], domains: ["growth", "relationships", "health"], tags: ["stoicism", "acceptance", "amor_fati", "epictetus", "wish", "event", "alignment", "resignation"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's Serenity — The Ataraxia", tradition: "Stoicism", source: "Epictetus, Discourses 1.4; Seneca, Letters 5", explanation: "The Stoic teaching: ataraxia — serenity, the undisturbed mind. The teaching's precision: serenity is not the absence of events but the absence of disturbance — the events continue, the disturbance ceases. The serenity is the practice's fruit, not its starting point.", application: "Use ataraxia as the library's serenity teaching: the practice's goal is not the events' cessation but the disturbance's. The application is the disturbance's release — not the world's change but the mind's. The library's calm entries inherit this.", questions: ["Where is my disturbance — and what is its source?", "What is the difference between serenity (undisturbed) and numbness (unfeeling)?", "Can I hold the events while releasing the disturbance?"], references: ["Epictetus, Discourses 1.4", "Seneca, Letters 5", "Marcus Aurelius, Meditations 4.3"], excerpt: "Ataraxia — serenity, the undisturbed mind. The events continue; the disturbance ceases.", evidence: "traditional", dimensions: ["emotion", "thought", "spirit"], paths: ["stoic", "raja"], domains: ["growth", "health", "self_care"], tags: ["stoicism", "ataraxia", "serenity", "undisturbed", "numbness", "events", "disturbance"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's Nature — Living According to Nature", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.40, 5.3, 6.38", explanation: "The Stoic teaching: live according to nature — the fundamental instruction. The teaching's precision: 'nature' is both cosmic (the logos's order) and human (the rational nature shared by all humans). To live according to nature is to live according to reason — both cosmic and human.", application: "Use living-according-to-nature as the library's alignment teaching: in any decision, ask 'is this according to nature — cosmic and human?' The application is the alignment's recognition — not the nature's definition but the alignment's practice.", questions: ["Where is my life — and is it according to nature?", "What is the difference between cosmic nature and human nature?", "Can I live according to nature — not as belief but as practice?"], references: ["Marcus Aurelius, Meditations 4.40", "Marcus Aurelius, Meditations 5.3", "Marcus Aurelius, Meditations 6.38"], excerpt: "Live according to nature — both cosmic (logos) and human (reason).", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["stoic", "karma"], domains: ["growth", "ethics", "work"], tags: ["stoicism", "nature", "living_according_to_nature", "cosmic", "human", "reason", "alignment"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Stoic's Universal Reason — The Logos's Presence", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.40, 6.38; Seneca, Letters 94", explanation: "The Stoic teaching: the logos is present in all things — the divine reason that orders the cosmos is the same reason that orders the human mind. The teaching's precision: the human mind is a fragment of the cosmic mind — not similar but continuous. The logos is the bridge between the individual and the universal.", application: "Use the logos's presence as the library's connection teaching: in any isolation, remember the logos's continuity. The application is the continuity's recognition — the mind is not isolated but continuous with the cosmos's reason.", questions: ["Where is my mind — and is it continuous with the cosmos's reason?", "What is the difference between similarity and continuity?", "Can I feel the logos's presence — not as belief but as recognition?"], references: ["Marcus Aurelius, Meditations 4.40", "Marcus Aurelius, Meditations 6.38", "Seneca, Letters 94"], excerpt: "The logos is present in all things — the mind is continuous with the cosmos's reason.", evidence: "traditional", dimensions: ["thought", "spirit", "connection"], paths: ["stoic", "jnana"], domains: ["learning", "spirituality", "relationships"], tags: ["stoicism", "logos", "universal_reason", "presence", "continuity", "mind", "cosmos"], difficulty: "advanced", minutes: 8 },
  { concept: "The Stoic's Simplicity — The Few Things", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 4.3, 7.19, 8.22", explanation: "The Stoic teaching: the few things — the sage needs few things, and the few are sufficient. Marcus Aurelius: 'How many things I do not need!' The teaching's precision: the reduction is not deprivation but recognition — the sage needs virtue, and virtue needs little. The few things are the sage's freedom.", application: "Use the few-things teaching as the library's simplicity practice: in the next week, reduce — not the practice's depth but the practice's accessories. The application is the reduction's recognition — the few things are sufficient; the many are distraction.", questions: ["Where is my practice's accumulation — and what is its cost?", "What is the difference between few (sufficient) and many (distracting)?", "Can I reduce to the few — and find them sufficient?"], references: ["Marcus Aurelius, Meditations 4.3", "Marcus Aurelius, Meditations 7.19", "Marcus Aurelius, Meditations 8.22"], excerpt: "How many things I do not need! The few things are the sage's freedom.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["stoic", "karma"], domains: ["growth", "self_care", "work"], tags: ["stoicism", "simplicity", "few_things", "marcus_aurelius", "reduction", "sufficient", "distraction"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's Time — The Present Moment", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 2.14, 8.36, 12.3", explanation: "The Stoic teaching: the present moment — the only time in which action is possible. Marcus Aurelius: never let the future disturb you; the future will come, if it comes, with the same nature as the present. The teaching's precision: the present is not a point but the field of action — the past is memory, the future is anticipation, the present is the only reality.", application: "Use the present-moment teaching as the library's temporal practice: in the next action, act in the present. The application is the temporal's recognition — not the future's denial but the present's priority. The library's micro-practices inherit this.", questions: ["Where is my action — in the present or in the anticipated?", "What is the difference between the present (reality) and the future (anticipation)?", "Can I act in the present — and let the future come as it comes?"], references: ["Marcus Aurelius, Meditations 2.14", "Marcus Aurelius, Meditations 8.36", "Marcus Aurelius, Meditations 12.3"], excerpt: "The present is the only field of action. Never let the future disturb you.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["stoic", "raja"], domains: ["growth", "work", "self_care"], tags: ["stoicism", "present_moment", "marcus_aurelius", "temporal", "action", "future", "anticipation", "reality"], difficulty: "beginner", minutes: 6 },
  { concept: "The Stoic's End — The Epilogue's Quiet", tradition: "Stoicism", source: "Marcus Aurelius, Meditations 12.36; Seneca, Letters 102", explanation: "The Stoic teaching: the end — death, the dissolution, the return to nature. Marcus Aurelius: the end is near; the things of the world are small and fleeting. The teaching's precision: the end is not feared but recognized — the end is the beginning's completion, not its negation. The Stoic's death is not the enemy but the conclusion.", application: "Use the end as the library's mortality teaching: the end is the practice's completion, not its negation. The application is the end's recognition — not the death's fear but the life's proportion. The library's mortality entries inherit this.", questions: ["Where is my practice's end — and what is its proportion?", "What is the difference between the end (completion) and the negation (loss)?", "Can I hold the end as the practice's completion — and live proportionately?"], references: ["Marcus Aurelius, Meditations 12.36", "Seneca, Letters 102", "Epictetus, Discourses 3.13"], excerpt: "The end is near; the things of the world are small and fleeting. The end is completion, not negation.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["stoic", "jnana"], domains: ["growth", "spirituality"], tags: ["stoicism", "end", "death", "marcus_aurelius", "seneca", "completion", "proportion", "mortality"], difficulty: "intermediate", minutes: 7 },
];
